    "answer": 3,
    "explanation": "定位：第四段「the average grocery basket has shrunk」，與前半句都市人口「risen steadily」形成對比，指單次採買量變小。(A) 錯：意思正好相反。(B) 錯：句中沒有方向轉變的語意，那屬於前一句的 shift。(C) 錯：擁擠形容的是空間，不能用來描述採買份量。"
